import{_ as o,a as t,b as i}from"./chunks/Desktop_Build.CQHeU67k.js";import{_ as n,o as a,c as l,ag as r}from"./chunks/framework.D9ghT4bC.js";const k=JSON.parse('{"title":"Building Locally","description":"","frontmatter":{},"headers":[],"relativePath":"Developers/Building-Locally.md","filePath":"Developers/Building-Locally.md"}'),s={name:"Developers/Building-Locally.md"};function d(c,e,u,h,p,g){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="building-locally" tabindex="-1">Building Locally <a class="header-anchor" href="#building-locally" aria-label="Permalink to &quot;Building Locally&quot;">​</a></h1><p>By the end of this guide, you will have Unciv running locally from code, so you can make changes and test them locally.</p><h2 id="with-android-studio" tabindex="-1">With Android Studio <a class="header-anchor" href="#with-android-studio" aria-label="Permalink to &quot;With Android Studio&quot;">​</a></h2><ul><li>Install <a href="https://developer.android.com/studio" target="_blank" rel="noreferrer">Android Studio</a> - it&#39;s free and awesome! Be aware that it&#39;s a long download!</li><li>Install Git, it&#39;s the way for us to work together on this project. UI is optional, Android Studio has good Git tools built in 😃</li><li>Getting the code <ul><li>Create a <a href="https://github.com/join" target="_blank" rel="noreferrer">Github account</a>, if you don&#39;t already have one</li><li><a href="https://github.com/yairm210/Unciv/fork" target="_blank" rel="noreferrer">Fork the repo</a> - this will create a &quot;copy&quot; of the code on your account, at <code>https://github.com/&lt;YourUsername&gt;/Unciv</code></li></ul></li><li>Load the project in Android Studio <ul><li>File -&gt; New -&gt; Project from Version Control -&gt; GitHub</li><li>Enter your GitHub username and password</li><li>Select the repository and hit clone - The GitHub repo will be created as a new project in Android Studio.</li></ul></li><li>Gradle will attempt the initial sync. If this is your first time with Android Studio, this may require you to accept the Android Build-tools licenses, which works differently on every device, so search for your OS-specific solution. <ul><li>A new install may not be able to do the initial sync - this comes in the form of <code>Unable to find method &#39;&#39;void org.apache.commons.compress.archivers.zip.ZipFile.&lt;init&gt;(java.nio.channels.SeekableByteChannel)&#39;&#39;</code> errors when you try to sync. If you have this problem go into File &gt; Settings &gt; Languages &amp; Frameworks &gt; Android SDK <ul><li>Click &quot;SDK Platforms&quot;</li><li>Click &quot;Android 16.0 (&quot;Baklava&quot;)&quot; <img src="'+o+'" alt="image"> (Optionally, you can save some space by selecting &#39;Show Package Details&#39; and choosing the Platform SDK only, without Sources or system Images)</li><li>Click &quot;SDK Tools&quot;</li><li>Select &quot;Show Package Details&quot; in the bottom right</li><li>Choose version 35.0.0 under &quot;Android SDK Build-Tools&quot; <img src="'+t+'" alt="image"></li><li>Click &quot;Apply&quot;</li><li>Restart Android Studio</li></ul></li></ul></li><li>Have patience and let the initial Gradle sync finish. The subsequent ones won&#39;t take as long. Watch the status bar or the &quot;Build&quot; toolpane.</li><li>If everything went well, you will now have three &quot;Run configurations&quot; (look for green in the top bar): &quot;android&quot;, &quot;Desktop&quot; and &quot;Run unit tests&quot;. <ul><li>If the &quot;android&quot; one is missing, it&#39;s likely your Android SDK setup did not set the ANDROID_HOME environment variable. Do so, restart Studio and re-sync Gradle (the button with the elephant and arrow in the top bar).</li><li>If the &quot;Desktop&quot; one is missing, here&#39;s how to create one manually: <ul><li>Select Run &gt; Edit configurations (from main menu or the configurations dropdown)</li><li>Click &quot;+&quot; to add a new configuration</li><li>Choose &quot;Application&quot;</li><li>Give the configuration a name, we recommend &quot;Desktop&quot;</li><li>Set the module classpath (the box to the right of the Java selection) to <code>Unciv.desktop.main</code> (<code>Unciv.desktop</code> for Bumblebee or below), main class to <code>com.unciv.app.desktop.DesktopLauncher</code> and <code>$ProjectFileDir$/android/assets</code> as the Working directory, OK to close the window <ul><li>It <em>may</em> be useful to set some VM options - activate the field in the run config editor with Alt-V or via the Modify Options menu, then add <code>-Xmx4096m -Xms256m -XX:MaxMetaspaceSize=256m</code> to allow a debugged game a little more memory. Or, use the <code>-DnoLog=</code> or <code>-DonlyLog=</code> options to control console logging. See the <a href="https://github.com/yairm210/Unciv/blob/master/core/src/com/unciv/utils/Log.kt" target="_blank" rel="noreferrer">Log.kt</a> comments for details.</li><li>If you get a <code>../../docs/uniques.md (No such file or directory)</code> error that means you forgot to set the working directory! <img src="'+i+`" alt="image"></li></ul></li></ul></li><li>If the &quot;Run unit tests&quot; is missing - look for the top-level &quot;tests&quot; folder, right-klick -&gt; Modify Run Configuration...</li></ul></li><li>Select the Desktop configuration (or however you chose to name it) and click the green arrow button to run! Or you can use the next button -the green critter with six legs and two feelers - to start debugging.</li><li>A few Android Studio settings that are recommended: <ul><li>Go to Settings &gt; Version Control &gt; Commit &gt; Advanced Commit and turn off &#39;Analyze code&#39;</li><li>On the same page, we recommend turning off &quot;Use non-modal commit interface&quot;. This puts the &quot;Local Changes and &quot;Console&quot; Tabs back into the Git toolpane (and the Shelf once you have shelved diffs). These can be hard to find otherwise - feel free to ignore if you don&#39;t think you need them.</li><li>Settings &gt; Editor &gt; Code Style &gt; Kotlin &gt; Tabs and Indents &gt; Continuation Indent: 4 <img src="https://user-images.githubusercontent.com/44038014/169315352-9ba0c4cf-307c-44d1-b3bc-2a58752c6854.png" alt="image"></li><li>Settings &gt; Editor &gt; General &gt; On Save &gt; Uncheck Remove trailing spaces on: [...] to prevent it from removing necessary trailing whitespace in template.properties for translation files <img src="https://user-images.githubusercontent.com/44038014/169316243-07e36b8e-4c9e-44c4-941c-47e634c68b4c.png" alt="image"><blockquote><p>Important: Unchecking this creates annoying merge conflicts. Before commits (non-translation) remove those trailing space. For more info check <a href="https://yairm210.github.io/Unciv/Developers/Coding-standards/" target="_blank" rel="noreferrer">Coding Standard</a>.</p></blockquote></li><li>Right-click the <code>android/assets/SaveFiles</code> folder once you have one, &quot;Mark directory as&quot; &gt; Excluded <ul><li>If you download mods do the same for the <code>android/assets/mods</code> folder and any other files you may create while testing that do not belong in the public project.</li><li>This <a href="https://www.jetbrains.com/help/idea/indexing.html#exclude" target="_blank" rel="noreferrer">disables indexing</a> for performance.</li></ul></li></ul></li></ul><p>Unciv uses Gradle to specify dependencies and how to run. In the background, the Gradle gnomes will be off fetching the packages (a one-time effort) and, once that&#39;s done, will build the project!</p><p>Unciv uses Gradle 8.11.1 and the Android Gradle Plugin 8.9.1. Can check in File &gt; Project Structure &gt; Project</p><blockquote><p>Note: advanced build commands (as described in the next paragraph), specifically <code>gradlew desktop:dist</code> to build a jar, run just fine in Android Studio&#39;s terminal (Alt+F12), with most dependencies already taken care of.</p></blockquote><h2 id="without-android-studio" tabindex="-1">Without Android Studio <a class="header-anchor" href="#without-android-studio" aria-label="Permalink to &quot;Without Android Studio&quot;">​</a></h2><ul><li>Ensure you have JDK 11 or higher installed</li><li>Clone the project (see above initial steps)</li><li>Open a terminal in the Unciv folder and run the following commands</li></ul><h3 id="windows-cmd" tabindex="-1">Windows (CMD) <a class="header-anchor" href="#windows-cmd" aria-label="Permalink to &quot;Windows (CMD)&quot;">​</a></h3><ul><li>Running: <code>gradlew desktop:run</code></li><li>Building: <code>gradlew desktop:dist</code></li></ul><h3 id="linux-macos-windows-powershell" tabindex="-1">Linux / macOS / Windows (PowerShell) <a class="header-anchor" href="#linux-macos-windows-powershell" aria-label="Permalink to &quot;Linux / macOS / Windows (PowerShell)&quot;">​</a></h3><ul><li>Running: <code>./gradlew desktop:run</code></li><li>Building: <code>./gradlew desktop:dist</code></li></ul><p>If the terminal returns <code>Permission denied</code> or <code>Command not found</code> on Mac/Linux, run <code>chmod +x ./gradlew</code> first. <em>This is a one-time procedure.</em></p><p>If you get an error that Android SDK folder wasn&#39;t found, install it by running:</p><p><code>sudo apt update &amp;&amp; sudo apt install android-sdk</code> (Debian, Ubuntu, Mint etc.)</p><p>Then, set the SDK location in the <code>local.properties</code> file by adding:</p><p><code>sdk.dir = /path/to/android/sdk</code> - for example, <code>/usr/lib/android-sdk</code></p><p>If during initial launch you get an error that the JDK version is wrong, install the JDK from <a href="https://adoptium.net/temurin/releases/" target="_blank" rel="noreferrer">here</a>.</p><blockquote><p>Note: Gradle may take up to several minutes to download files After building, the output .JAR file should be in <code>/desktop/build/libs/Unciv.jar</code></p></blockquote><p>For actual development, you&#39;ll probably need to download Android Studio and build it yourself - see above 😃</p><h2 id="debugging-on-android" tabindex="-1">Debugging on Android <a class="header-anchor" href="#debugging-on-android" aria-label="Permalink to &quot;Debugging on Android&quot;">​</a></h2><p>Sometimes, checking things out on the desktop version is not enough and you need to debug Unciv running on an Android device. For an introduction, see <a href="./Testing-Android-Builds.html">Testing android builds</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>Congratulations! Unciv should now be running on your computer! Now we can start changing some code, and later we&#39;ll see how your changes make it into the main repository!</p><p>Now would be a good time to get to know the project in general at <a href="./Project-structure-and-major-classes.html">the Project Structure overview!</a></p><h3 id="unit-tests" tabindex="-1">Unit Tests <a class="header-anchor" href="#unit-tests" aria-label="Permalink to &quot;Unit Tests&quot;">​</a></h3><p>You can (and in some cases <em>should</em>) run and even debug the unit tests locally.</p><ul><li>The repository contains a run configuration &quot;Run unit tests&quot;. If it&#39;s missing:</li><li>In Android Studio, Run &gt; Edit configurations. <ul><li>Click &quot;+&quot; to add a new configuration</li><li>Choose &quot;Gradle&quot; and name the config, e.g. &quot;Run unit tests&quot;</li><li>Under &quot;Gradle Project&quot;, choose &quot;Unciv&quot; from the dropdown (or type it), set &quot;Tasks&quot; to <code>:tests:test</code> and &quot;Arguments&quot; to <code>--tests &quot;com.unciv.*&quot;</code>, OK to close the window.</li></ul></li><li>Select the &quot;Run unit tests&quot; configuration and click the green arrow button to run! Or start a debug session as above.</li></ul><h3 id="linting" tabindex="-1">Linting <a class="header-anchor" href="#linting" aria-label="Permalink to &quot;Linting&quot;">​</a></h3><p>Detekt checks for code smells and other linting issues. To generate Detekt reports:</p><ul><li>Download <a href="https://github.com/detekt/detekt/releases/latest" target="_blank" rel="noreferrer">detekt-cli</a> (the zip file) and unzip it</li><li>Open a terminal in the Unciv root directory and run one of the following commands to generate the report. NOTE: If you&#39;re using Windows, replace <code>detekt-cli</code> with <code>detekt-cli.bat</code>. <ul><li>For warnings: <code>PATH/TO/DETEKT/detekt-cli --parallel --report html:detekt/reports.html --config .github/workflows/detekt_config/detekt-warnings.yml</code></li><li>For errors: <code>PATH/TO/DETEKT/detekt-cli --parallel --report html:detekt/reports.html --config .github/workflows/detekt_config/detekt-errors.yml</code></li></ul></li><li>The report will be generated in <code>detekt/reports.html</code></li></ul><h3 id="testing-wiki-changes" tabindex="-1">Testing wiki changes <a class="header-anchor" href="#testing-wiki-changes" aria-label="Permalink to &quot;Testing wiki changes&quot;">​</a></h3><p>This wiki is automatically built from <a href="https://github.com/yairm210/Unciv/tree/master/docs" target="_blank" rel="noreferrer">the main repository&#39;s &#39;docs&#39; folder</a>, so to help improve it, you would normally work on those files in a branch of your local Unciv clone.</p><p>However, typical editor previews of markdown are <em><strong>NOT</strong></em> authoritative, as the files get processed by <code>mkdocs</code>. For a conclusive check, run <code>mkdocs</code> locally and view the result in your browser.</p><p>Once set up, it&#39;s a simple <code>mkdocs serve</code> from Android Studio&#39;s terminal, or if you chose the simpler Windows setup, <code>python -m mkdocs serve</code>.</p><p>The command will tell you the link it&#39;s serving on, and e.g. in Android Studio&#39;s shell, you can click it. The server will monitor the source for changes, so you can edit while your test is running and see the changes almost immediately. (Look up when Android Studio actually saves to disk, or hit Ctrl-S to make sure. The browser won&#39;t need a manual refresh!)</p><p>The one-time setup procedure is as follows:</p><ul><li>Install python <ul><li>Linux: <code>sudo apt install python3 python-is-python3 -y</code> or however you prefer</li><li>Windows: Get it from python.org/downloads - look for &quot;standalone installer&quot;</li></ul></li><li>Install mkdocs and required plugins <ul><li>Run <code>pip install mkdocs mkdocs-material mkdocs-awesome-pages-plugin</code>.</li><li>On Debian-based Linux, you&#39;ll run into the &quot;virtual environment&quot; hassle, so either learn to manage that or add the <code>--break-system-packages</code> option.</li></ul></li><li>Manage PATH <ul><li><p>On Windows, the python scripts folder is not added to the PATH by default.</p><p><code>pip install</code> will tell you about that, and show the correct location.</p><p>Add <code>%AppData%\\Python\\Python314\\Scripts</code> (adjust version as required) to your path, or use the more verbose command as shown.</p></li></ul></li></ul><h3 id="cleaning-up-obsolete-files" tabindex="-1">Cleaning up obsolete files <a class="header-anchor" href="#cleaning-up-obsolete-files" aria-label="Permalink to &quot;Cleaning up obsolete files&quot;">​</a></h3><p>From time to time, Unciv bumps the versions of major tools - mainly Gradle, the Android SDK Platform, and the Android SDK Build-Tools. The new versions and support files are automatically downloaded for you, but old versions are not cleaned up automatically, nor are intermediate build files specific to Gradle versions. This may leave a few gigabytes of dead files on your system. If these bother you, you can clean up as follows:</p><ul><li>Remove obsolete Android SDK Platform and Build-Tools versions from SDK manager (remember all projects share these, so if you have other projects, keep their requirements too).</li><li>With Android Studio closed (on Windows, you&#39;ll have to manually kill leftover Gradle daemons too): <ul><li>Delete subfolders named after obsolete Gradle versions from Unciv/.gradle, ~/.gradle/caches (%HOME%.gradle\\caches on Windows) and ~/.gradle/daemon</li><li>For a thorough but more costly cleanup, clean out ~/.gradle/caches entirely except for the tag files. This will force the next gradle sync to re-download a large amount of support files, but this way you will also clean out remnants of superseded support libraries for kotlin, Gdx and so on.</li></ul></li></ul><p>Additionally, git prioritizes safety of your changes over efficiency to the extreme, leading to some bloat. <code>git gc</code> is automatically done for you, but sparingly, and running it manually won&#39;t hurt. For a more thorough cleanup, run <code>git gc --prune=now --aggressive</code> sporadically from Studio&#39;s terminal (or any shell within Unicv&#39;s project folder), making sure to clean up all your obsolete branches first, and that all remaining branches are in sync with the online branches they&#39;re backing or based on master if they&#39;re local only.</p><h3 id="uncivserver" tabindex="-1">UncivServer <a class="header-anchor" href="#uncivserver" aria-label="Permalink to &quot;UncivServer&quot;">​</a></h3><p>The simple multiplayer host included in the sources can be set up to debug or run analogously to the main game:</p><ul><li>In Android Studio, Run &gt; Edit configurations. <ul><li>Click &quot;+&quot; to add a new configuration</li><li>Choose &quot;Application&quot; and name the config, e.g. &quot;UncivServer&quot;</li><li>Set the module to <code>Unciv.server.main</code> (<code>Unciv.server</code> for Studio versions Bumblebee or below), main class to <code>com.unciv.app.server.UncivServer</code> and <code>&lt;repo_folder&gt;/android/assets/</code> as the Working directory, OK to close the window.</li></ul></li><li>Select the UncivServer configuration and click the green arrow button to run! Or start a debug session as above.</li></ul><p>To build a jar file, refer to <a href="#without-android-studio">Without Android Studio</a> and replace &#39;desktop&#39; with &#39;server&#39;. That is, run <code>./gradlew server:dist</code> and when it&#39;s done look for /server/build/libs/UncivServer.jar</p><h3 id="uncivsrv-typescript-server" tabindex="-1">UncivSrv (TypeScript server) <a class="header-anchor" href="#uncivsrv-typescript-server" aria-label="Permalink to &quot;UncivSrv (TypeScript server)&quot;">​</a></h3><p>The feature-complete multiplayer server lives in the <code>server-ts/</code> submodule (<a href="https://github.com/blyrin/unciv-srv" target="_blank" rel="noreferrer">blyrin/unciv-srv</a>) — WebSocket chat, web admin panel, SQLite storage with automatic migrations, login rate limiting, scheduled cleanup, and more. It requires Node.js 20+ and pnpm 10+:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server-ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # type check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # run Vitest tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # run with tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # build &amp; run the compiled output</span></span></code></pre></div><p>Configuration is read from a <code>.env</code> file — see <code>server-ts/example.env</code> for the available options.</p><p>The submodule also ships <code>Dockerfile</code> / <code>docker-compose.yml</code> for containerized deployment — <code>docker compose up -d --build</code> in <code>server-ts/</code>, with the SQLite database persisted on a <code>/data</code> volume. See its README for details.</p>`,52)])])}const y=n(s,[["render",d]]);export{k as __pageData,y as default};
